import React, { useEffect, useRef, useState } from "react";
import { useCountries } from "react-countries";
import { useTranslation } from "react-i18next";

const NationalitySelect = ({ value, onChange, name = "nationality" }) => {
  const { t } = useTranslation();
  const { countries } = useCountries();

  const [isOpen, setIsOpen] = useState(false);
  const containerRef = useRef(null);
  const listRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  // Scroll selected option into view when opened (matches native behavior)
  useEffect(() => {
    if (isOpen && listRef.current) {
      const selectedEl = listRef.current.querySelector('[data-selected="true"]');
      if (selectedEl) {
        selectedEl.scrollIntoView({ block: "nearest" });
      }
    }
  }, [isOpen]);

  const handleSelect = (countryName) => {
    onChange({ target: { name, value: countryName } });
    setIsOpen(false);
  };

  return (
    <div className="flex flex-col gap-1.5" ref={containerRef}>
      <label className="text-xs-custom font-semibold text-gray-700 uppercase tracking-wider">
        {t("Nationality")}
      </label>

      <div className="relative">
        <button
          type="button"
          onClick={() => setIsOpen((prev) => !prev)}
          className="w-full flex items-center justify-between px-4 py-2.5 text-sm-custom border border-gray-200 rounded-xl outline-none focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 transition-all bg-white text-left"
        >
          <span className={value ? "text-gray-800" : "text-gray-400"}>
            {value || t("Select Country")}
          </span>
          <i className="fa fa-chevron-down text-xs text-gray-400"></i>
        </button>

        {isOpen && (
          <ul
            ref={listRef}
            className="absolute z-20 mt-1 w-full max-h-64 overflow-y-auto bg-white border border-gray-200 rounded-xl shadow-lg py-1"
          >
            {countries?.map(({ name: countryName }) => {
              const isSelected = value === countryName;
              return (
                <li key={countryName} data-selected={isSelected}>
                  <button
                    type="button"
                    onClick={() => handleSelect(countryName)}
                    className={`w-full text-left px-4 py-2 text-sm-custom transition-colors ${
                      isSelected
                        ? "bg-brand-500 text-white"
                        : "text-gray-700 hover:bg-brand-50"
                    }`}
                  >
                    {countryName}
                  </button>
                </li>
              );
            })}
          </ul>
        )}
      </div>
    </div>
  );
};

export default NationalitySelect;