// src/components/GUI/EmployeeContractForm.jsx
import React from "react";
import { useTranslation } from "react-i18next";
import AppCard from "./AppCard";
import AppInput from "./AppInput";
import AppButton from "./AppButton";
import SearchableDropdown from "../layout/SearchableDropdown";
import AppInfoBox from "../layout/AppInfoBox";

const STAFF_ROLES = [
  "teacher",
  "principal",
  "finance",
  "admin",
  "manager",
  "assistant",
  "librarian",
];

const EmployeeContractForm = ({
  isEditMode,
  contract, // entire contract state object
  onChange, // (field, value) => void
  onAllowanceChange, // (field, value) => void
  onSubmit,
  isSubmitting, // boolean – creating or updating

  // Employee dropdown
  employeeSearch,
  onEmployeeSearch,
  employeeOptions,
  employeesLoading,
  preselectedEmployeeName,
  employeeReadOnly, // true when employeeIdFromUrl or isEditMode
  employeeValue, // the id

  // Role dropdown
  roleOptions,
  roleValue,
  onRoleChange,

  // Campus dropdown
  campusSearch,
  onCampusSearch,
  campusOptions,
  campusesLoading,
  campusValue,
  onCampusChange,

  // Academic Year dropdown
  academicYearSearch,
  onAcademicYearSearch,
  academicYearOptions,
  academicYearsLoading,
  academicYearValue,
  onAcademicYearChange,
  academicYearDisabled,
}) => {
  const { t } = useTranslation();

  const { employee, role, campus, academicYear, startDate, endDate, baseSalary, allowances, status, note } = contract;

  const statusOptions = ["active", "suspended", "terminated", "completed", "transferred", "expired"];

  // Allow local role options if not passed
  const finalRoleOptions = roleOptions || STAFF_ROLES.map((r) => ({
    value: r,
    label: t(r.charAt(0).toUpperCase() + r.slice(1)),
  }));

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      <AppCard
        title={t("Contract Information")}
        icon="fa-file-contract"
        footer={
          <div className="flex justify-end gap-3">
            <AppButton backUrl="/admin/employee-contracts" />
            <AppButton
              type="submit"
              label={isEditMode ? t("Update Contract") : t("Create Contract")}
              loadingLabel={t("Saving...")}
              isLoading={isSubmitting}
              icon="fa-save"
            />
          </div>
        }
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Employee field */}
          <div className="md:col-span-2">
            {employeeReadOnly ? (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  {t("Employee")} <span className="text-red-500">*</span>
                </label>
                {/* ✅ FIX: removed className="bg-gray-100" — it was completely
                    wiping out AppInput's rounded-xl/border/focus styles
                    instead of adding to them (now fixed at the AppInput
                    level too, but no longer needed here since disabled
                    styling is now built into AppInput itself). */}
                <AppInput value={preselectedEmployeeName || employeeValue} disabled />
                <p className="text-xs text-gray-500 mt-1">{t("Employee is pre‑selected")}</p>
              </div>
            ) : (
              <SearchableDropdown
                label={t("Employee")}
                value={employeeValue}
                options={employeeOptions}
                onChange={(val) => onChange("employee", val)}
                onSearch={onEmployeeSearch}
                placeholder={t("Select Staff Member")}
                isLoading={employeesLoading}
                required
              />
            )}
          </div>

          {/* Role */}
          <SearchableDropdown
            label={t("Role")}
            value={role}
            options={finalRoleOptions}
            onChange={(val) => onChange("role", val)}
            placeholder={t("Select Role")}
            required
          />

          {/* Campus */}
          <SearchableDropdown
            label={t("Campus")}
            value={campus}
            options={campusOptions}
            onChange={(val) => onChange("campus", val)}
            onSearch={onCampusSearch}
            placeholder={t("Select Campus")}
            isLoading={campusesLoading}
            required
          />

          {/* Academic Year */}
          <SearchableDropdown
            label={t("Academic Year")}
            value={academicYear}
            options={academicYearOptions}
            onChange={(val) => onChange("academicYear", val)}
            onSearch={onAcademicYearSearch}
            placeholder={t("Select Academic Year")}
            isLoading={academicYearsLoading}
            required
            disabled={academicYearDisabled}
          />

          {/* Base Salary */}
          <AppInput
            label={t("Base Salary")}
            type="number"
            name="baseSalary"
            value={baseSalary}
            onChange={(e) => onChange("baseSalary", e.target.value)}
            required
            min="0"
            step="0.01"
          />

          {/* Start Date */}
          <AppInput
            label={t("Start Date")}
            type="date"
            name="startDate"
            value={startDate}
            onChange={(e) => onChange("startDate", e.target.value)}
            required
          />

          {/* End Date */}
          <AppInput
            label={t("End Date")}
            type="date"
            name="endDate"
            value={endDate}
            onChange={(e) => onChange("endDate", e.target.value)}
            helperText={t("Optional. Leave blank if still active.")}
          />
        </div>

        {/* Allowances */}
        <div className="mt-6">
          <h4 className="text-sm font-semibold text-gray-700 mb-2">{t("Allowances")}</h4>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <AppInput
              label={t("House Rent")}
              type="number"
              name="allowances.houseRent"
              value={allowances.houseRent}
              onChange={(e) => onAllowanceChange("houseRent", e.target.value)}
              min="0"
              step="0.01"
            />
            <AppInput
              label={t("Medical")}
              type="number"
              name="allowances.medical"
              value={allowances.medical}
              onChange={(e) => onAllowanceChange("medical", e.target.value)}
              min="0"
              step="0.01"
            />
          </div>
        </div>

        {/* Status select */}
        <div className="mt-4">
          <label className="block text-sm font-medium text-gray-700 mb-1">{t("Status")}</label>
          <select
            value={status}
            onChange={(e) => onChange("status", e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-md text-sm"
          >
            {statusOptions.map((s) => (
              <option key={s} value={s}>
                {t(s.charAt(0).toUpperCase() + s.slice(1))}
              </option>
            ))}
          </select>
        </div>

        {/* Note */}
        <div className="mt-4">
          {/* ✅ FIX: was type="text" with an unsupported `multiline` prop —
              AppInput doesn't recognize `multiline`, so this rendered as a
              single-line input and silently ignored `rows`. Use
              type="textarea" instead, which AppInput already supports. */}
          <AppInput
            label={t("Note (optional)")}
            type="textarea"
            name="note"
            value={note}
            onChange={(e) => onChange("note", e.target.value)}
            rows={3}
          />
        </div>

        <AppInfoBox icon="fa-info-circle" className="mt-6">
          <strong>{t("Note")}:</strong>{" "}
          {t("Overlapping contracts for the same employee and academic year are not allowed.")}
        </AppInfoBox>
      </AppCard>
    </form>
  );
};

export default EmployeeContractForm;
