import React, { useState, useRef, useEffect } from "react";
import { useSelector } from "react-redux";
import { Link, useLocation } from "react-router-dom";
import { useLazyLogoutQuery, useGetMeQuery } from "../../redux/api/authApi";
import { Cog6ToothIcon, ChevronDownIcon, Bars3Icon, XMarkIcon, CalendarIcon } from "@heroicons/react/24/outline";
import LanguageSwitcher from "../LanguageSwitcher";
import { useGetCampusQuery, useSetCampusTokenMutation } from "../../redux/api/campusApi";
import dayjs from "dayjs";
import { useTranslation } from "react-i18next";
import { useGetAcademicYearsListQuery } from "../../redux/api/academicYearApi";

const Header = () => {
  const { t } = useTranslation();
  const getCookie = (name) => {
    const cookieString = document.cookie;
    const cookies = cookieString.split('; ');
    for (let cookie of cookies) {
      const [cookieName, cookieValue] = cookie.split('=');
      if (cookieName === name) return decodeURIComponent(cookieValue);
    }
    return null;
  };

  // Helper to delete a cookie
  const deleteCookie = (name, path = '/') => {
    document.cookie = `${name}=; path=${path}; expires=Thu, 01 Jan 1970 00:00:00 UTC`;
  };

  const location = useLocation();
  const { isLoading } = useGetMeQuery();
  const { data: campusData, isLoading: campusLoading } = useGetCampusQuery({ limit: 0 });
  const [setCampusToken] = useSetCampusTokenMutation();
  const [logout] = useLazyLogoutQuery();
  const { isAuthenticated, user } = useSelector((state) => state.auth);

  // Fetch academic years list (for dropdown)
  const { data: academicYearsData, isLoading: academicYearsLoading } = useGetAcademicYearsListQuery(
    { limit: 0, sort: "-createdAt" },
    { skip: !isAuthenticated }
  );

  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  // Academic year states – store both ID and name
  const [selectedAcademicYear, setSelectedAcademicYear] = useState(() => {
    return getCookie('academicYear') || '';
  });
  const [selectedAcademicYearName, setSelectedAcademicYearName] = useState(() => {
    return getCookie('academicYearName') || '';
  });

  const dropdownTimeoutRef = useRef(null);

  const [selectedCampus, setSelectedCampus] = useState(() => {
    const cookieCampus = getCookie('campus');
    return cookieCampus || user?.campus?._id || '';
  });

  // ✅ FIX: keys must match the User model's `role` enum exactly
  // ("principal", "counselor") — the old "principle"/"counsellor" spelling
  // meant these roles always fell through to the generic "Dashboard" title.
  const roleTitles = {
    user: t("User Dashboard"),
    admin: t("Admin Dashboard"),
    teacher: t("Teacher Dashboard"),
    student: t("Student Dashboard"),
    finance: t("Finance Dashboard"),
    principal: t("Principal Dashboard"),
    counselor: t("Counsellor Dashboard"),
  };

  const dashboardTitle = roleTitles[user?.role] || t("Dashboard");

  // Academic year cookies handling – read both ID and name
  useEffect(() => {
    const storedAcademicYear = getCookie('academicYear');
    const storedAcademicYearName = getCookie('academicYearName');
    if (storedAcademicYear) {
      setSelectedAcademicYear(storedAcademicYear);
    }
    if (storedAcademicYearName) {
      setSelectedAcademicYearName(storedAcademicYearName);
    }
  }, []);

  // If academic year ID is set but name is missing, try to fill it from loaded data
  useEffect(() => {
    if (selectedAcademicYear && !selectedAcademicYearName && academicYearsData?.academicYears) {
      const found = academicYearsData.academicYears.find(y => y._id === selectedAcademicYear);
      if (found && found.name) {
        setSelectedAcademicYearName(found.name);
        document.cookie = `academicYearName=${encodeURIComponent(found.name)}; path=/; max-age=${60 * 60 * 24 * 365}`;
      }
    }
  }, [academicYearsData, selectedAcademicYear, selectedAcademicYearName]);

  // If user object loads later, ensure selectedCampus is set (in case cookie was missing)
  useEffect(() => {
    if (!selectedCampus && user?.campus?._id) {
      setSelectedCampus(user.campus._id);
    }
  }, [user, selectedCampus]);

  const handleMouseEnter = () => {
    clearTimeout(dropdownTimeoutRef.current);
    setIsDropdownOpen(true);
  };

  const handleMouseLeave = () => {
    dropdownTimeoutRef.current = setTimeout(() => {
      setIsDropdownOpen(false);
    }, 300);
  };

  const handleCampusChange = (value) => {
    setSelectedCampus(value);
    setCampusToken(value)
      .unwrap()
      .then((response) => {
        if (response.success) window.location.reload();
      })
      .catch((err) => console.error(err));
  };

  // Academic year change handler – save both ID and name to cookies
  const handleAcademicYearChange = (e) => {
    const yearId = e.target.value;
    const selectedOption = e.target.selectedOptions[0];
    const yearName = selectedOption ? selectedOption.text : '';

    setSelectedAcademicYear(yearId);
    setSelectedAcademicYearName(yearName);

    document.cookie = `academicYear=${encodeURIComponent(yearId)}; path=/; max-age=${60 * 60 * 24 * 365}`;
    document.cookie = `academicYearName=${encodeURIComponent(yearName)}; path=/; max-age=${60 * 60 * 24 * 365}`;

    window.location.reload();
  };

  // Updated logout handler: clears storage AND cookies
  const logoutHandler = () => {
    logout().then(() => {
      // Clear browser storage
      localStorage.clear();
      sessionStorage.clear();

      // Delete specific cookies that should not persist after logout
      deleteCookie('academicYear');
      deleteCookie('academicYearName');
      deleteCookie('campus'); // remove campus cookie as well, if desired

      // Redirect to home / login page
      window.location.href = "/";
    });
  };

  // ✅ FIX: the User model has no `name` field — only firstName/middleName/
  // lastName. `user?.name` was always undefined; build the display name
  // from the fields that actually exist.
  const displayName = [user?.firstName, user?.lastName].filter(Boolean).join(" ") || t("User");

  if (location.pathname === "/") return null;

  return (
    <nav className="sticky top-0 z-50 bg-white/90 backdrop-blur-lg border-b border-gray-100 px-4 md:px-8 py-3 font-sans">
      <div className="flex items-center justify-between">

        {/* LEFT: Brand & Title Section */}
        <div className="flex items-center space-x-6">
          <Link to="/" className="flex items-center space-x-3 group">
            <div className="w-10 h-10 bg-gradient-to-br from-brand-600 to-brand-700 rounded-xl flex items-center justify-center shadow-soft group-hover:rotate-3 transition-transform">
              <img src="/images/Logo.png" alt="Logo" className="w-7 h-7 brightness-200" />
            </div>
            <div className="hidden xl:block">
              <h1 className="text-lg-custom font-heading font-black tracking-tight text-dark leading-none">
                School<span className="text-brand-600">Sync</span>
              </h1>
              <p className="text-nav-caption font-bold text-slate-400 uppercase mt-1">
                {t("Management Pro")}
              </p>
            </div>
          </Link>

          <div className="hidden md:block h-8 w-[1px] bg-gray-200 mx-2"></div>

          <h2 className="text-lg-custom md:text-xl-custom font-heading font-extrabold text-dark tracking-tight">
            {dashboardTitle}
          </h2>
        </div>

        {/* RIGHT: Actions & User Info */}
        <div className="flex items-center space-x-4 lg:space-x-8">

          {/* Status & Login Info (Desktop) */}
          <div className="hidden lg:flex items-center space-x-4 border-r border-gray-100 pr-6">
            <div className="text-right">
              <p className="text-nav-caption font-bold text-slate-400 uppercase">{t("Last Session")}</p>
              <div className="flex items-center text-sm-custom font-semibold text-slate-700">
                <CalendarIcon className="w-3.5 h-3.5 mr-1 text-brand-500" />
                {dayjs().format('DD MMM, YYYY')}
              </div>
            </div>
            <span className="px-3 py-1 bg-brand-50 text-brand-600 rounded-lg text-nav-caption font-black uppercase border border-brand-100">
              {user?.role || t("User")}
            </span>
          </div>

          <div className="flex items-center space-x-3">
            <LanguageSwitcher />

            {/* Academic Year Selector (only for authenticated users) – moved here, right after language switcher */}
            {isAuthenticated && (
              <div className="relative group hidden sm:block">
                <select
                  className="appearance-none bg-surface-50 border border-gray-200 text-slate-700 py-1.5 px-3 pr-8 rounded-lg focus:outline-none focus:ring-2 focus:ring-brand-500/10 transition-all cursor-pointer text-xs-custom font-bold disabled:opacity-50 disabled:cursor-not-allowed"
                  value={selectedAcademicYear}
                  onChange={handleAcademicYearChange}
                  disabled={academicYearsLoading}
                >
                  <option value="">{t("Select Academic Year")}</option>
                  {academicYearsData?.academicYears?.map((year) => (
                    <option key={year._id} value={year._id}>
                      {year.name}
                    </option>
                  ))}
                </select>
                <ChevronDownIcon className="w-3 h-3 absolute right-2 top-2.5 text-gray-400 pointer-events-none" />
              </div>
            )}

            {/* Campus selector / display */}
            {isAuthenticated && (
              <>
                {user?.role === "admin" ? (
                  <div className="relative hidden md:block">
                    <select
                      className="appearance-none bg-brand-600 text-white py-1.5 px-3 pr-8 rounded-lg focus:outline-none shadow-md shadow-brand-600/30 cursor-pointer text-xs-custom font-bold"
                      value={selectedCampus}
                      onChange={(e) => handleCampusChange(e.target.value)}
                    >
                      {campusLoading ? (
                        <option>{t("Loading...")}</option>
                      ) : (
                        campusData?.campuses?.map((c) => (
                          <option key={c._id} value={c._id}>{c.name}</option>
                        ))
                      )}
                    </select>
                    <ChevronDownIcon className="w-3 h-3 absolute right-2 top-2.5 text-brand-100 pointer-events-none" />
                  </div>
                ) : (
                  user?.campus?.name && (
                    <span className="hidden md:inline-block px-3 py-1 bg-surface-100 text-slate-700 rounded-lg text-xs-custom font-bold">
                      {user.campus.name}
                    </span>
                  )
                )}
              </>
            )}
          </div>

          {/* User Profile Dropdown */}
          {isAuthenticated && (
            <div className="relative" onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
              <button className="flex items-center space-x-2 p-1 rounded-xl hover:bg-surface-50 transition-all">
                <div className="relative">
                  <img
                    src={user?.avatar ? user?.avatar?.url : "/images/default_avatar.jpg"}
                    alt="User"
                    className="w-9 h-9 rounded-lg object-cover ring-2 ring-white shadow-md"
                  />
                  <span className="absolute -bottom-1 -right-1 w-3 h-3 bg-emerald-500 border-2 border-white rounded-full"></span>
                </div>
                <Cog6ToothIcon className="w-5 h-5 text-gray-400 hover:rotate-90 transition-transform duration-500" />
              </button>

              {isDropdownOpen && (
                <div className="absolute right-0 mt-2 w-60 bg-white rounded-2xl shadow-premium border border-surface-100 py-2 overflow-hidden animate-slide-up">
                  <div className="px-4 py-3 bg-surface-50/50 border-b border-surface-50">
                    <p className="text-sm-custom font-black text-dark truncate">{displayName}</p>
                    <p className="text-nav-caption text-brand-600 font-bold uppercase">{user?.email}</p>
                  </div>
                  <div className="p-2 space-y-1">
                    <Link to="/me/profile" className="flex items-center px-3 py-2 text-sm-custom text-slate-600 hover:bg-brand-50 hover:text-brand-700 rounded-lg transition-colors">
                      <i className="fas fa-id-badge mr-3 opacity-70"></i> {t("My Profile")}
                    </Link>
                    {user?.role === "admin" && (
                      <Link to="/admin/dashboard" className="flex items-center px-3 py-2 text-sm-custom text-slate-600 hover:bg-brand-50 hover:text-brand-700 rounded-lg transition-colors">
                        <i className="fas fa-th-large mr-3 opacity-70"></i> {t("Control Panel")}
                      </Link>
                    )}
                    <button onClick={logoutHandler} className="flex items-center w-full px-3 py-2 text-sm-custom text-red-600 hover:bg-red-50 rounded-lg font-bold transition-colors">
                      <i className="fas fa-power-off mr-3 opacity-70"></i> {t("Sign Out")}
                    </button>
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Mobile Menu Toggle */}
          <button className="md:hidden p-2 text-gray-600" onClick={() => setMenuOpen(!menuOpen)}>
            {menuOpen ? <XMarkIcon className="w-6 h-6" /> : <Bars3Icon className="w-6 h-6" />}
          </button>
        </div>
      </div>
    </nav>
  );
};

export default Header;
