import React from "react";
import { useTranslation } from "react-i18next";
import moment from "moment";
import AppCard from "../GUI/AppCard";
import AppButton from "../GUI/AppButton";
import AppBadge from "../GUI/AppBadge";

const EmploymentActions = ({
  campusLabel,
  activeContract,
  onTransferClick,
  onTerminateClick,
}) => {
  const { t } = useTranslation();

  return (
    <AppCard
      title={t("Employment Actions")}
      icon="fa-briefcase"
      subtitle={t("Manage campus assignment and contract status")}
    >
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div>
          <p className="text-[11px] font-semibold text-gray-500 uppercase mb-1">
            {t("Current Campus")}
          </p>
          <p className="text-sm text-gray-800">{campusLabel}</p>
        </div>
        <div>
          <p className="text-[11px] font-semibold text-gray-500 uppercase mb-1">
            {t("Active Contract")}
          </p>
          {activeContract ? (
            <div className="flex flex-wrap items-center gap-2">
              <AppBadge type="contractStatus" value={activeContract.status} />
              <span className="text-sm text-gray-600">
                {t("Since")}{" "}
                {moment(activeContract.startDate).format("DD MMM YYYY")}
              </span>
            </div>
          ) : (
            <p className="text-sm text-gray-500">{t("No active contract")}</p>
          )}
        </div>
      </div>

      <div className="flex flex-wrap gap-3">
        <AppButton
          label={t("Transfer Employee")}
          icon="fa-right-left"
          variant="secondary"
          onClick={onTransferClick}
          disabled={!activeContract}
        />
        <AppButton
          label={t("Terminate Contract")}
          icon="fa-user-xmark"
          variant="danger"
          onClick={onTerminateClick}
          disabled={!activeContract}
        />
      </div>
    </AppCard>
  );
};

export default EmploymentActions;
