import React from "react";
import { useTranslation } from "react-i18next";
import moment from "moment";
import AppCard from "../GUI/AppCard";
import AppBadge from "../GUI/AppBadge";

const ContractHistory = ({ contracts = [], isLoading = false }) => {
  const { t } = useTranslation();

  return (
    <AppCard
      title={t("Contract History")}
      icon="fa-history"
      subtitle={t("All contracts for this employee")}
    >
      {isLoading ? (
        <div className="text-center py-4 text-gray-500">
          {t("Loading contracts...")}
        </div>
      ) : contracts.length === 0 ? (
        <div className="text-center py-4 text-gray-500">
          {t("No contracts found for this employee.")}
        </div>
      ) : (
        <div className="overflow-y-auto max-h-[200px] border border-gray-200 rounded-lg">
          <table className="min-w-full text-sm">
            <thead className="bg-gray-50 sticky top-0">
              <tr>
                <th className="px-3 py-2 text-left font-medium text-gray-600">
                  {t("Start Date")}
                </th>
                <th className="px-3 py-2 text-left font-medium text-gray-600">
                  {t("End Date")}
                </th>
                <th className="px-3 py-2 text-left font-medium text-gray-600">
                  {t("Status")}
                </th>
                <th className="px-3 py-2 text-left font-medium text-gray-600">
                  {t("Campus")}
                </th>
                <th className="px-3 py-2 text-left font-medium text-gray-600">
                  {t("Role")}
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {contracts.map((contract) => (
                <tr key={contract._id} className="hover:bg-gray-50">
                  <td className="px-3 py-2 whitespace-nowrap">
                    {moment(contract.startDate).format("DD MMM YYYY")}
                  </td>
                  <td className="px-3 py-2 whitespace-nowrap">
                    {contract.endDate
                      ? moment(contract.endDate).format("DD MMM YYYY")
                      : "—"}
                  </td>
                  <td className="px-3 py-2">
                    <AppBadge type="contractStatus" value={contract.status} />
                  </td>
                  <td className="px-3 py-2">{contract.campus?.name || "—"}</td>
                  <td className="px-3 py-2">{contract.role || "—"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </AppCard>
  );
};

export default ContractHistory;