import React, { useEffect, useState } from "react";
import { toast } from "react-hot-toast";
import { useSelector } from "react-redux";
import { useLocation, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import { useGetStaffNeedingContractQuery } from "../../redux/api/employeeContractApi";

import AdminLayout from "../layout/AdminLayout";
import Loader from "../layout/Loader";
import MetaData from "../layout/MetaData";
import { DataTableContainer } from "../GUI/DataTableContainer";
import AppButton from "../GUI/AppButton";
import FilterDropdown from "../GUI/FilterDropdown";
import EmptyState from "../GUI/EmptyState";
import TruncatedCell from "../GUI/TruncatedCell";
import AppBadge from "../GUI/AppBadge";
import PhoneLink from "../GUI/PhoneLink";

const ListEmployeeContracts = () => {
  const { t } = useTranslation();
  const location = useLocation();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);

  const [userRole, setUserRole] = useState("");
  const [search, setSearch] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [limit, setLimit] = useState(8);

  const { data, isLoading, error, refetch, isFetching } =
    useGetStaffNeedingContractQuery({});

  useEffect(() => {
    if (location.state?.showSuccessToast) {
      toast.success(t("Contract updated successfully!"));
      navigate(location.pathname, { replace: true, state: {} });
    }
  }, [location.state, navigate, t, location.pathname]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setSearchTerm(search);
      setCurrentPage(1);
    }, 500);
    return () => clearTimeout(timer);
  }, [search]);

  useEffect(() => {
    refetch();
  }, []);

  useEffect(() => {
    if (location.state?.shouldRefetch) {
      refetch();
      window.history.replaceState({}, document.title);
    }
  }, [location.state, refetch]);

  useEffect(() => {
    if (error) toast.error(error?.data?.message || t("Something went wrong"));
    if (user?.role === "admin") setUserRole("admin");
  }, [error, user, t]);

  const handleRefresh = () => {
    refetch();
    toast.success(t("Refreshed"));
  };

  const getFullName = (row) => {
    const u = row.user;
    const { firstName = "", middleName = "", lastName = "" } = u;
    return `${firstName} ${middleName ? middleName + " " : ""}${lastName}`.trim();
  };

  const columns = [
    {
      header: t("Teacher Name"),
      accessor: "user.firstName",
      width: "35%",
      minWidth: "200px",
      render: (_, row) => (
        <TruncatedCell maxChars={35}>{getFullName(row)}</TruncatedCell>
      ),
    },
    {
      header: t("Status"),
      accessor: "user.status",
      width: "15%",
      minWidth: "100px",
      render: (value) => {
        const isActive = value === "active";
        return <AppBadge type="booleanStatus" active={isActive} />;
      },
    },
    {
      header: t("Phone Number"),
      width: "20%",
      minWidth: "150px",
      render: (_, row) => <PhoneLink number={row.user?.phoneNumber} />,
    },
    {
      header: t("Action"),
      accessor: "action",
      width: "20%",
      minWidth: "150px",
      render: (_, row) => {
        const existing = row.existingContract;
        return (
          <AppButton
            label={existing ? t("Update Contract") : t("Create Contract")}
            icon={existing ? "edit" : "plus"}
            onClick={() => {
              if (existing) {
                navigate(`/admin/employee-contracts/edit?contractId=${existing._id}`);
              } else {
                navigate(`/admin/employee-contracts/new?employeeId=${row.user._id}`);
              }
            }}
            size="sm"
          />
        );
      },
    },
  ];

  const staffList = data?.staff || [];

  const stats = [
    {
      label: t("Pending Contracts"),
      value: staffList.length,
      icon: "clock",
      color: "orange",
    },
  ];

  const addButton =
    userRole === "admin" ? (
      <AppButton to="/admin/employee-contracts/new" label={t("New Contract")} icon="plus" />
    ) : null;

  const refreshButton = (
    <AppButton
      onClick={handleRefresh}
      text={t("Refresh")}
      icon="sync-alt"
      disabled={isFetching}
      className="ml-2"
    />
  );

  const filters = (
    <FilterDropdown
      limit={limit}
      onLimitChange={(newLimit) => {
        setLimit(newLimit);
        setCurrentPage(1);
      }}
      onReset={() => {
        setSearch("");
        setSearchTerm("");
        setCurrentPage(1);
        setLimit(8);
      }}
    >
      <div className="text-sm text-gray-500">
        {t("Teachers who need a contract for the current campus/year.")}
      </div>
    </FilterDropdown>
  );

  const emptyState = (
    <EmptyState
      icon="user-tie"
      title={
        searchTerm
          ? t("No teachers found matching your search")
          : t("All teachers have contracts")
      }
      message={t("No pending contracts for this campus and academic year.")}
    />
  );

  if (isLoading) return <Loader />;

  return (
    <AdminLayout>
      <MetaData title={t("Teacher Contracts")} />

      <DataTableContainer
        title={t("Teacher Contract Management")}
        subtitle={t("Manage contracts for teachers who need them")}
        data={staffList}
        columns={columns}
        isLoading={isLoading}
        isFetching={isFetching}
        pagination={null}
        currentPage={currentPage}
        setCurrentPage={setCurrentPage}
        limit={limit}
        setLimit={setLimit}
        search={search}
        setSearch={setSearch}
        searchTerm={searchTerm}
        setSearchTerm={setSearchTerm}
        searchPlaceholder={t("Search teachers...")}
        onRefresh={handleRefresh}
        refreshButton={refreshButton}
        addButton={addButton}
        emptyState={emptyState}
        filters={filters}
        stats={stats}
        userRole={userRole}
        renderHeaderInfo={() => (
          <p className="text-sm text-gray-500 mt-1">
            <i className="fa fa-info-circle mr-2"></i>
            {t("Showing")}: {staffList.length} {t("teachers")}
          </p>
        )}
        className="teacher-contract-table-container"
        showSearch={true}
        showStats={true}
        showPagination={false}
      />
    </AdminLayout>
  );
};

export default ListEmployeeContracts;
