import React from "react";
import DatePickerField from "./DatePickerField";

const AppInput = ({
  label,
  name,
  value,
  onChange,
  type = "text",
  placeholder,
  required = false,
  rows = 3,
  helperText,
  className, // ✅ pulled out separately so it MERGES instead of overriding
  ...props
}) => {
  const baseClass =
    "w-full px-4 py-2.5 text-sm-custom border border-gray-200 rounded-xl focus:ring-2 focus:ring-brand-500/20 focus:border-brand-500 outline-none transition-all bg-white placeholder:text-gray-400 accent-brand-500 disabled:bg-gray-50 disabled:text-gray-500 disabled:cursor-not-allowed";

  // ✅ ROOT-CAUSE FIX: previously `{...props}` (which could contain a
  // `className`) was spread AFTER `className={inputClass}` in JSX — when
  // a prop appears twice, the LATER one wins. So any custom className
  // passed in (e.g. "bg-gray-100") completely WIPED OUT rounded-xl /
  // border / focus-ring instead of adding to it. Now they're merged.
  const inputClass = `${baseClass} ${className || ""}`.trim();

  return (
    <div className="flex flex-col gap-1.5">
      {label && (
        <label className="text-xs-custom font-semibold text-gray-700 uppercase tracking-wider">
          {label} {required && <span className="text-red-500 ml-1">*</span>}
        </label>
      )}

      {type === "textarea" ? (
        <textarea
          name={name}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          rows={rows}
          className={inputClass}
          {...props}
        />
      ) : type === "date" ? (
        // Native date input's calendar popup is OS-rendered and its blue
        // highlight can't be recolored via CSS — replaced with a fully
        // custom calendar so every color is brand-themed.
        <DatePickerField
          name={name}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          min={props.min}
          max={props.max}
          disabled={props.disabled}
        />
      ) : (
        <input
          type={type}
          name={name}
          value={value}
          onChange={onChange}
          placeholder={placeholder}
          className={inputClass}
          {...props}
        />
      )}

      {helperText && <p className="text-xs text-gray-400">{helperText}</p>}
    </div>
  );
};

export default AppInput;
